/** Browser-only story fixture. Every mount gets its own editor and explicit cleanup. */
import { Editor, createSurface } from "@nooq/editor";
import type { Plugin, JsonValue } from "@nooq/plugins";
import type { DOMPlugin } from "@nooq/plugins/dom";
export interface PluginStoryArgs { fields?: Record<string, JsonValue>; text?: string; children?: boolean }
const editors = new Set<Editor>();
export function mountPluginStory(plugin: Plugin, dom: DOMPlugin, args: PluginStoryArgs = {}): HTMLElement {
  const editor = new Editor({ docId: crypto.randomUUID(), actor: { actorId: "human:story" }, plugins: [plugin] });
  editors.add(editor);
  try {
    const definition = plugin.contributes.blocks![0]!, defaults = definition.create();
    const id = editor.insertBlock({ type: definition.type, parent: null, fields: args.fields ?? defaults.fields, text: args.text ?? defaults.text?.s ?? "" });
    if (args.children) editor.insertBlock({ type: "unknown.child/v1", parent: id, text: "Nested child" });
    return createSurface(editor, { plugins: [dom] }).element;
  } catch (error) { editor.close(); editors.delete(editor); throw error; }
}
export function disposePluginStories(): void { for (const editor of editors) editor.close(); editors.clear(); }

Use standard CSF3 Meta<PluginStoryArgs>/StoryObj<PluginStoryArgs> from @storybook/html-vite (type-only), expect from storybook/test, and the supplied mountPluginStory helper. Export ALL named stories from brief.view.stories. Each requires a play function with awaited assertions using canvas role/label queries. Get userEvent from the play context: play: async ({canvas,userEvent}) => {...}. Default MUST edit the textbox with userEvent.clear/type and assert the resulting value, as in the scaffold. KeyboardCycle must focus the native button (button.focus() or awaited tab), activate with await userEvent.keyboard("{Enter}") and assert the visible changed field. Initial focus is not guaranteed. NestedContent uses args.children:true and asserts canvas.getByRole("textbox",{name:"Text block"}) with toHaveValue("Nested child"), since textarea values are not text nodes. InvalidTone uses an invalid stored field, clicks the button and checks that the invalid value remains. Cover default, alternate field states and text editing. beforeEach must return disposePluginStories as cleanup. Never disable a11y or test checks, catch failed assertions, use fixture IDs, import the editor directly, or change the oracle. These stories run with Storybook's composition/run lifecycle in Chromium, in light and dark themes, followed by an independent axe audit.
